async function settle(){await page.evaluate(()=>document.fonts.ready);await page.waitForTimeout(150)}
async function shot(name){await settle();const file=String(++n).padStart(2,'0')+'-'+name+'.png';await page.screenshot({path:path.join(out,file),animations:'disabled'});screens.push({file,name,config});await noOverflow(name);}
