async function menu(name){const trigger=page.getByRole('button',{name:'Menü öffnen',exact:true});await trigger.click();await page.locator('.structured-app-menu').waitFor();const states=[];for(let i=0;i<15;i++){await page.keyboard.press(i<10?'Tab':'Shift+Tab');states.push(await page.evaluate(()=>!!document.activeElement.closest('.structured-app-menu')))}check(name+'.focus-contained',states.every(Boolean),states);await shot(name+'-menu');await page.keyboard.press('Escape');check(name+'.focus-restored',await trigger.evaluate(e=>e===document.activeElement));}
